.tool-page{max-width:950px;margin:38px auto;padding:0 18px}.tool-panel{padding:clamp(20px,5vw,36px);border:1px solid #e2e9f8;border-radius:24px;background:#fff;box-shadow:0 14px 38px #1e3a8a0b}.tool-panel h1{margin:10px 0;color:#172554;font-size:clamp(1.8rem,6vw,2.5rem)}.tool-panel .intro{color:#71809a;line-height:1.8}.json-editor{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}.editor-label{display:block;margin-bottom:8px;font-weight:800;color:#34466b}.json-area{width:100%;min-height:300px;padding:14px;border:1px solid #dbe4f4;border-radius:14px;background:#f9fbff;color:#1e293b;font: .88rem/1.65 ui-monospace,SFMono-Regular,Consolas,monospace;resize:vertical}.tool-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px}.tool-actions button{border:0;border-radius:11px;padding:11px 15px;background:#315eea;color:white;font:inherit;font-weight:800;cursor:pointer}.tool-actions .secondary{background:#eef2ff;color:#315eea}.json-status{min-height:26px;margin-top:12px;font-size:.85rem;font-weight:750}.json-status.ok{color:#059669}.json-status.error{color:#dc2626}.dark .tool-panel{background:#111c34;border-color:#263652}.dark .tool-panel h1,.dark .editor-label{color:#e5edff}.dark .json-area{background:#0b1428;border-color:#2b3b58;color:#e5edff}.dark .tool-actions .secondary{background:#1b2d50;color:#b8c8ff}@media(max-width:700px){.json-editor{grid-template-columns:1fr}.json-area{min-height:210px}}
</style></head><body><header class="site-header"><div class="header-inner"><a class="brand" href="/"><span class="brand-mark">⚒</span><span class="brand-name">Toolkit<span class="brand-pro">Pro</span><small>আপনার অনলাইন টুলস</small></span></a><div class="header-actions"><button class="language-toggle" type="button" aria-label="Switch to English">EN</button><a class="text-link" href="/">← সব টুলস</a></div></div></header><main class="tool-page"><section class="tool-panel"><span class="hero-kicker">DEVELOPER TOOL · FREE</span><h1>JSON Formatter</h1><p class="intro">JSON পেস্ট করে যাচাই করুন, সুন্দরভাবে সাজান অথবা ছোট করে মিনিফাই করুন। তথ্য আপনার ব্রাউজারেই প্রসেস হয়।</p><div class="json-editor"><div><label class="editor-label" for="jsonInput">JSON ইনপুট</label><textarea id="jsonInput" class="json-area" spellcheck="false" placeholder='{"name":"ToolkitPro","tools":3}'></textarea></div><div><label class="editor-label" for="jsonOutput">ফলাফল</label><textarea id="jsonOutput" class="json-area" readonly spellcheck="false" placeholder="সাজানো JSON এখানে দেখাবে…"></textarea></div></div><div class="tool-actions"><button id="formatBtn">Format / Validate</button><button id="minifyBtn" class="secondary">Minify</button><button id="copyBtn" class="secondary">ফলাফল কপি</button><button id="clearBtn" class="secondary">মুছে ফেলুন</button></div><div id="status" class="json-status" role="status"></div></section></main><script>
const inp=document.getElementById('jsonInput'),out=document.getElementById('jsonOutput'),status=document.getElementById('status');function process(minify=false){try{const obj=JSON.parse(inp.value);out.value=minify?JSON.stringify(obj):JSON.stringify(obj,null,2);status.className='json-status ok';status.textContent='✓ বৈধ JSON';}catch(e){out.value='';status.className='json-status error';status.textContent='JSON ত্রুটি: '+e.message;}}document.getElementById('formatBtn').addEventListener('click',()=>process(false));document.getElementById('minifyBtn').addEventListener('click',()=>process(true));document.getElementById('clearBtn').addEventListener('click',()=>{inp.value='';out.value='';status.textContent='';inp.focus();});document.getElementById('copyBtn').addEventListener('click',async()=>{if(!out.value)return;try{await navigator.clipboard.writeText(out.value);status.className='json-status ok';status.textContent='ফলাফল কপি হয়েছে ✓';}catch(e){out.select();document.execCommand('copy');status.textContent='কপি সম্পন্ন';}});
</script><script src="/assets/language.js" defer></script></body></html>